package de.s04tv.fireedition;

import android.webkit.WebView;

/**
 * Kiosk-sized presentation for the original 3Q embed on S04TV video pages.
 * It does not issue a cross-origin fullscreen request, alter media playback
 * or seek, or replace the player with a different video implementation.
 */
final class VideoTvMode {
    private VideoTvMode() {}

    static void present(WebView view) {
        if (view != null) view.evaluateJavascript(SCRIPT, null);
    }

    private static final String SCRIPT = "(function(){\n  if(location.protocol!=='https:'||location.hostname!=='tv.schalke04.de'||!/^\\/videos\\//.test(location.pathname))return;\n  if(window.__s04tvVideoTvMode)return;\n  var timer=null,observer=null,active=null,oldStyles=null,started=Date.now();\n  function isVideo(){\n    return location.protocol==='https:'&&location.hostname==='tv.schalke04.de'&&/^\\/videos\\//.test(location.pathname);\n  }\n  function suitable(el){\n    if(!el||!el.isConnected)return false;\n    var r=el.getBoundingClientRect();\n    return r.width>230&&r.height>110;\n  }\n  function findPlayer(){\n    // 3Q streams commonly use a hosted iframe. Keep the iframe and its original\n    // media pipeline intact, just display it across the TV viewport.\n    var frames=document.querySelectorAll('iframe');\n    for(var i=0;i<frames.length;i++){\n      var f=frames[i],src=f.getAttribute('src')||'';\n      if(/(?:3qsdn\\.com|3q\\.de|playout\\.3q)/i.test(src)&&suitable(f))return f;\n    }\n    for(var i=0;i<frames.length;i++){\n      var f=frames[i],title=f.getAttribute('title')||'',allow=f.getAttribute('allow')||'';\n      if(suitable(f)&&/player|video|fullscreen/i.test(title+' '+allow))return f;\n    }\n    var vids=document.querySelectorAll('video');\n    for(var i=0;i<vids.length;i++){\n      var v=vids[i];if(!suitable(v))continue;\n      var best=v;\n      for(var p=v.parentElement,depth=0;p&&p!==document.body&&depth<5;p=p.parentElement,depth++){\n        var r=p.getBoundingClientRect();\n        if(r.width>=250&&r.width<=Math.max(innerWidth*1.2,1000)&&\n           r.height>=130&&r.height<=Math.max(innerHeight*1.4,800))\n           best=p;\n      }\n      return best;\n    }\n    return null;\n  }\n  function prepareAncestors(node){\n    for(var p=node.parentElement;p&&p!==document.documentElement;p=p.parentElement){\n      if(p===document.body)break;\n      // Reset clipping/transform context only along the selected player path.\n      if(!p.hasAttribute('data-s04tv-tv-ancestor')){\n        p.setAttribute('data-s04tv-tv-ancestor','1');\n        p.style.setProperty('overflow','visible','important');\n        p.style.setProperty('transform','none','important');\n        p.style.setProperty('contain','none','important');\n        p.style.setProperty('filter','none','important');\n        p.style.setProperty('z-index','2147482000','important');\n      }\n    }\n  }\n  function present(el){\n    if(active===el)return;\n    if(active){\n      // A dynamically replaced embed is treated as a new player.\n      active.removeAttribute('data-s04tv-fullscreen-video');\n    }\n    active=el;\n    prepareAncestors(el);\n    el.setAttribute('data-s04tv-fullscreen-video','1');\n    var style=document.getElementById('s04tv-tv-video-css');\n    if(!style){\n      style=document.createElement('style');\n      style.id='s04tv-tv-video-css';\n      style.textContent=[\n        'html,body{margin:0!important;background:#000!important}',\n        '[data-s04tv-fullscreen-video]{position:fixed!important;left:0!important;top:0!important;',\n        'right:0!important;bottom:0!important;width:100vw!important;height:100vh!important;',\n        'min-width:100vw!important;min-height:100vh!important;max-width:none!important;',\n        'max-height:none!important;aspect-ratio:auto!important;margin:0!important;',\n        'padding:0!important;border:0!important;object-fit:contain!important;',\n        'display:block!important;visibility:visible!important;background:#000!important;',\n        'z-index:2147483000!important;}',\n        '[data-s04tv-fullscreen-video] video{width:100%!important;height:100%!important;object-fit:contain!important}'\n      ].join('');\n      (document.head||document.documentElement).appendChild(style);\n    }\n    try{scrollTo(0,0);}catch(e){}\n  }\n  function scan(){\n    if(!isVideo()){if(timer)clearInterval(timer);if(observer)observer.disconnect();return;}\n    var player=findPlayer();\n    if(player)present(player);\n    if(Date.now()-started>30000){if(timer)clearInterval(timer);if(observer)observer.disconnect();}\n  }\n  window.__s04tvVideoTvMode={refresh:scan};\n  observer=new MutationObserver(function(){if(!active||!active.isConnected)scan();});\n  observer.observe(document.documentElement||document,{subtree:true,childList:true});\n  timer=setInterval(scan,600);\n  scan();\n})();";
}
